package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanDescription;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.deser.CreatorProperty;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.AnnotatedWithParams;
import com.fasterxml.jackson.databind.deser.impl.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.std.StdValueInstantiator;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.type.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Member;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class CreatorCollector_addDelegatingCreator_TriageGen1Test {

    private CreatorCollector creatorCollector;
    private BeanDescription beanDescription;
    private MapperConfig<?> mapperConfig;
    private AnnotatedWithParams creator;
    private SettableBeanProperty[] injectables;

    // Constants extracted from logic (assuming these exist in the class context)
    // Since they are private/internal, we assume they are accessible or mocked via reflection if needed, 
    // but here we focus on the branch logic.
    private static final int C_ARRAY_DELEGATE = 1; // Dummy value for testing
    private static final int C_DELEGATE = 2;      // Dummy value for testing

    @Before
    public void setUp() {
        beanDescription = mock(BeanDescription.class);
        mapperConfig = mock(MapperConfig.class);
        creatorCollector = spy(new CreatorCollector(beanDescription, mapperConfig));
        creator = mock(AnnotatedWithParams.class);
        injectables = new SettableBeanProperty[]{mock(SettableBeanProperty.class)};
    }

    /**
     * Tests the branch where the parameter type is a Collection-like type.
     * This should trigger the C_ARRAY_DELEGATE path.
     */
    @Test
    public void testAddDelegatingCreator_WithCollectionLikeType() {
        // Arrange
        JavaType collectionType = mock(JavaType.class);
        when(collectionType.isCollectionLikeType()).thenReturn(true);
        when(creator.getParameterType(0)).thenReturn(collectionType);

        // Act
        creatorCollector.addDelegatingCreator(creator, true, injectables);

        // Assert
        // Verify verifyNonDup was called with the array delegate constant
        // Note: In a real scenario, we'd check if C_ARRAY_DELEGATE is the actual value used in the class
        verify(creatorCollector).verifyNonDup(eq(creator), anyInt(), eq(true));

        // Since _arrayDelegateArgs is private, we verify through side effects if possible 
        // or rely on the fact that no exception was thrown and code path was covered.
    }

    /**
     * Tests the branch where the parameter type is NOT a Collection-like type.
     * This should trigger the C_DELEGATE path.
     */
    @Test
    public void testAddDelegatingCreator_WithNonCollectionLikeType() {
        // Arrange
        JavaType nonCollectionType = mock(JavaType.class);
        when(nonCollectionType.isCollectionLikeType()).thenReturn(false);
        when(creator.getParameterType(0)).thenReturn(nonCollectionType);

        // Act
        creatorCollector.addDelegatingCreator(creator, false, injectables);

        // Assert
        verify(creatorCollector).verifyNonDup(eq(creator), anyInt(), eq(false));
    }

    /**
     * Tests the scenario where verifyNonDup might throw an exception (Duplicate detection).
     * This ensures the exception propagation is handled/tested.
     */
    @Test(expected = RuntimeException.class)
    public void testAddDelegatingCreator_ThrowsExceptionOnDuplicate() {
        // Arrange
        JavaType collectionType = mock(JavaType.class);
        when(collectionType.isCollectionLikeType()).thenReturn(true);
        when(creator.getParameterType(0)).thenReturn(collectionType);

        // Force verifyNonDup to throw an exception
        doThrow(new RuntimeException("Duplicate creator")).when(creatorCollector)
                .verifyNonDup(eq(creator), anyInt(), anyBoolean());

        // Act
        creatorCollector.addDelegatingCreator(creator, true, injectables);
    }

    /**
     * Test with null injectables to ensure robustness (Line coverage for edge cases).
     */
    @Test
    public void testAddDelegatingCreator_WithNullInjectables() {
        // Arrange
        JavaType nonCollectionType = mock(JavaType.class);
        when(nonCollectionType.isCollectionLikeType()).thenReturn(false);
        when(creator.getParameterType(0)).thenReturn(nonCollectionType);

        // Act
        creatorCollector.addDelegatingCreator(creator, true, null);

        // Assert
        verify(creatorCollector).verifyNonDup(eq(creator), anyInt(), eq(true));
    }
}
